for (int f=0;f<=5;f+=(b%25==0&&w%50==0)?1:5) for (int t=0;t<=5;t+=(b%25==0&&w%50==0)?1:5) for (int n=0;n<=5;n+=(b%25==0&&w%50==0)?1:5) foreach (var j in jams)
