  var stock = new NoteCounts(f,t,n); var acc = new AccountState(b,w); total++;
  var d = new Lenient(stock, j);
  var r = new CashMachine(d).Execute(acc, new Operation.Withdraw(a));
  var e = Expect(acc, stock, j, a);
  if (r != e.Item1 || d.Stock != e.Item2) { if (bad++ < 15) Console.WriteLine($"{acc} {stock} {j} {a}: {r} vs {e.Item1}"); }
}
