static (AtmResult, NoteCounts) Expect(AccountState acc, NoteCounts s, Denomination? j, int a) {
  (AtmResult, NoteCounts) R(AtmStatus st) => (new(st, default, 0, acc), s);
  if (a<=0||a%10!=0) return R(AtmStatus.InvalidAmount);
  if (acc.WithdrawnToday+a>200) return R(AtmStatus.DailyLimitExceeded);
  int fee = a>100?5:0; if (a+fee>acc.Balance) return R(AtmStatus.InsufficientFunds);
  var av = j switch { Denomination.Fifty => s with {Fifties=0}, Denomination.Twenty => s with {Twenties=0}, Denomination.Ten => s with {Tens=0}, _ => s };
  NoteCounts? best=null;
  for (int f=0;f<=av.Fifties;f++) for (int t=0;t<=av.Twenties;t++) for (int n=0;n<=av.Tens;n++) { var c=new NoteCounts(f,t,n); if (c.Value==a && (best==null||c.Total<best.Value.Total)) best=c; }
  if (best is not {} cb) return R(AtmStatus.CannotDispense);
  return (new(AtmStatus.Ok, cb, fee, new(acc.Balance-a-fee, acc.WithdrawnToday+a)), s-cb);
}
